def parse_json(s: str) -> object:
    """
    A recursive descent parser for a simplified JSON format. 
    It reads the input string character by character to construct 
    corresponding Python objects based on the JSON syntax.
    """

    index = 0

    def skip_whitespace():
        nonlocal index
        while index < len(s) and s[index].isspace():
            index += 1

    def parse_value():
        nonlocal index
        skip_whitespace()
        if index >= len(s):
            raise ValueError("Unexpected end of JSON input.")

        char = s[index]
        if char == '"':
            return parse_string()
        elif char.isdigit() or char == '-':
            return parse_number()
        elif s.startswith("true", index):
            index += 4
            return True
        elif s.startswith("false", index):
            index += 5
            return False
        elif s.startswith("null", index):
            index += 4
            return None
        elif char == "[":
            return parse_array()
        elif char == "{":
            return parse_object()
        else:
            raise ValueError(f"Unexpected character '{char}'")

    def parse_string():
        nonlocal index
        index += 1  # skip the initial quote
        start_index = index
        while index < len(s):
            char = s[index]
            if char == '"':
                result = s[start_index:index]
                index += 1  # skip the closing quote
                return unescape_string(result)
            elif char == "\\":
                index += 1  # skip the backslash and continue
            index += 1
        raise ValueError("Unterminated string")

    def unescape_string(s: str) -> str:
        return bytes(s, "utf-8").decode("unicode_escape")

    def parse_number():
        nonlocal index
        start_index = index
        if s[index] == '-':
            index += 1
        while index < len(s) and s[index].isdigit():
            index += 1
        if index < len(s) and s[index] == '.':
            index += 1
            while index < len(s) and s[index].isdigit():
                index += 1
        result = s[start_index:index]
        try:
            return int(result) if '.' not in result else float(result)
        except ValueError:
            raise ValueError(f"Invalid number: {result}")

    def parse_array():
        nonlocal index
        index += 1  # skip the opening bracket
        array = []
        skip_whitespace()
        if s[index] == ']':
            index += 1  # empty array
            return array
        while index < len(s):
            value = parse_value()
            array.append(value)
            skip_whitespace()
            if s[index] == ']':
                index += 1
                return array
            elif s[index] != ',':
                raise ValueError("Expected ',' or ']' in array")
            index += 1  # skip the comma
            skip_whitespace()

    def parse_object():
        nonlocal index
        index += 1  # skip the opening brace
        obj = {}
        skip_whitespace()
        if s[index] == '}':
            index += 1  # empty object
            return obj
        while index < len(s):
            key = parse_string()
            skip_whitespace()
            if s[index] != ':':
                raise ValueError("Expected ':' in object")
            index += 1  # skip the colon
            value = parse_value()
            obj[key] = value
            skip_whitespace()
            if s[index] == '}':
                index += 1
                return obj
            elif s[index] != ',':
                raise ValueError("Expected ',' or '}' in object")
            index += 1  # skip the comma
            skip_whitespace()

    return parse_value()

