        elif s.startswith("null", index):
            index += 4
            return None
        elif char == "[":
            return parse_array()
        elif char == "{":
            return parse_object()
        else:
            raise ValueError(f"Unexpected character: {char}")

    def parse_string():
        string_value = ''
        next_char()  # Skip initial quote
        while True:
            char = next_char()
            if char == '"':
                return string_value
