                        index += 4
                    else:
                        raise ValueError("Invalid Unicode escape sequence")
            else:
                string_value += char

    def parse_number():
        number_str = ''
        if peek_char() == '-':
            number_str += next_char()
        while peek_char() and peek_char().isdigit():
