        if peek_char() == '.':
            number_str += next_char()
            while peek_char() and peek_char().isdigit():
                number_str += next_char()
        return float(number_str) if '.' in number_str else int(number_str)

    def parse_array():
        array = []
        next_char()  # Skip opening bracket
        skip_whitespace()
        if peek_char() == ']':
            next_char()  # Skip closing bracket
            return array
        while True:
            array.append(parse_value())
            skip_whitespace()
            char = next_char()
            if char == ']':
                return array
            elif char != ',':
                raise ValueError("Expected ',' or ']' in array")
            skip_whitespace()

    def parse_object():
        obj = {}
        next_char()  # Skip opening brace
        skip_whitespace()
        if peek_char() == '}':
            next_char()  # Skip closing brace
