            char = next_char()
            if char == '}':
                return obj
            elif char != ',':
                raise ValueError("Expected ',' or '}' in object")
            skip_whitespace()

    def skip_whitespace():
        while peek_char() and peek_char().isspace():
            next_char()

    return parse_value()

